<?php
declare(strict_types=1);
namespace App\Http\Controllers\Api\V1;
use App\Models\FleetManagement\TransporterProfile;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\Rule;
final class LiveBookingsController extends PartnerController {
 private function vendor(Request $r):TransporterProfile{[$v,$role]=$this->context($r);abort_unless($role==='vendor'&&$v->isActive(),403,'Active vendor account required.');return $v;}
 public function index(Request $r){$v=$this->vendor($r);DB::table('live_bookings')->where('status','pending_confirmation')->where('confirm_token_expires_at','<=',now())->update(['status'=>'open','confirmed_vendor_id'=>null,'confirm_token_hash'=>null,'confirm_token_expires_at'=>null,'updated_at'=>now()]);$i=$r->validate(['date_from'=>['nullable','date'],'date_to'=>['nullable','date','after_or_equal:date_from'],'time_from'=>['nullable','date_format:H:i'],'time_to'=>['nullable','date_format:H:i'],'trip_type'=>['nullable',Rule::in(['one_way','round_trip','local'])],'from_city'=>['nullable','string','max:150'],'to_city'=>['nullable','string','max:150'],'car_type'=>['nullable','string','max:80'],'scope'=>['sometimes',Rule::in(['open','confirmed'])],'page'=>['sometimes','integer','min:1']]);
  $scope=$i['scope']??'open';$cool=DB::table('live_booking_vendor_cooldowns')->where('vendor_id',$v->id)->where('cooldown_until','>',now())->value('cooldown_until');$free=\App\Services\PartnerMarketplaceAlerts::freeCabs((int)$v->id);$q=DB::table('live_bookings');if($scope==='confirmed')$q->where('status','confirmed')->where('confirmed_vendor_id',$v->id);else $q->whereIn('status',['open','pending_confirmation'])->where('expires_at','>',now())->where(function($w)use($v){$w->whereExists(function($q)use($v){$q->selectRaw('1')->from('live_booking_interests as i')->whereColumn('i.live_booking_id','live_bookings.id')->where('i.vendor_id',$v->id);})->orWhereExists(function($q)use($v){$q->selectRaw('1')->from('partner_market_free_cabs as f')->where('f.vendor_id',$v->id)->where('f.is_free',true)->whereColumn('f.available_from','<=','live_bookings.pickup_at')->whereColumn('f.available_until','>=','live_bookings.pickup_at');});});foreach(['trip_type','from_city','to_city','car_type'] as $k)if(!empty($i[$k]))$q->where($k,'like',$k==='trip_type'?$i[$k]:'%'.$i[$k].'%');if(!empty($i['date_from']))$q->whereDate('pickup_at','>=',$i['date_from']);if(!empty($i['date_to']))$q->whereDate('pickup_at','<=',$i['date_to']);if(!empty($i['time_from']))$q->whereTime('pickup_at','>=',$i['time_from']);if(!empty($i['time_to']))$q->whereTime('pickup_at','<=',$i['time_to']);
  $rows=$q->orderBy('pickup_at')->limit(300)->get()->filter(function($row)use($free){return collect($free)->contains(fn($cab)=>\App\Services\LiveBookingMatching::cab($row,$cab));})->values();if($cool&&$scope==='open')$rows=collect();$page=\Illuminate\Pagination\LengthAwarePaginator::resolveCurrentPage();$items=$rows->forPage($page,30)->values();foreach($items as $row){unset($row->requester_phone,$row->source_sender,$row->source_group_id,$row->source_message_id,$row->confirm_token_hash);$row->my_interest=DB::table('live_booking_interests')->where('live_booking_id',$row->id)->where('vendor_id',$v->id)->value('status');$row->interested_count=DB::table('live_booking_interests')->where('live_booking_id',$row->id)->where('status','interested')->count();}
  return response()->json(['status'=>true,'data'=>['items'=>$items,'page'=>$page,'last_page'=>max(1,(int)ceil($rows->count()/30)),'cooldown_until'=>$cool]])->header('Cache-Control','private, no-store');
 }
 public function contact(Request $r,int $id){$v=$this->vendor($r);$b=DB::table('live_bookings')->where('id',$id)->where('status','confirmed')->where('confirmed_vendor_id',$v->id)->first();abort_unless($b,403,'Contact is available only to the confirmed vendor.');return response()->json(['status'=>true,'data'=>['requester_phone'=>$b->requester_phone,'requester_name'=>$b->requester_name]]);}
 public function interest(Request $r,int $id){$v=$this->vendor($r);DB::table('live_bookings')->where('status','pending_confirmation')->where('confirm_token_expires_at','<=',now())->update(['status'=>'open','confirmed_vendor_id'=>null,'confirm_token_hash'=>null,'confirm_token_expires_at'=>null,'updated_at'=>now()]);$b=DB::table('live_bookings')->where('id',$id)->whereIn('status',['open','pending_confirmation'])->where('expires_at','>',now())->first();abort_unless($b,404);DB::table('live_booking_interests')->updateOrInsert(['live_booking_id'=>$id,'vendor_id'=>$v->id],['status'=>'interested','updated_at'=>now(),'created_at'=>now()]);return response()->json(['status'=>true,'message'=>'Interest saved. Booking remains visible to all vendors.']);}
 public function dutyReceived(Request $r,int $id){$v=$this->vendor($r);return DB::transaction(function()use($id,$v){$b=DB::table('live_bookings')->where('id',$id)->lockForUpdate()->first();abort_unless($b&&$b->status==='open'&&now()->lt($b->expires_at),409,'Live booking is no longer open.');abort_unless(DB::table('live_booking_interests')->where('live_booking_id',$id)->where('vendor_id',$v->id)->exists(),403,'Show interest before confirming duty.');$token=bin2hex(random_bytes(24));DB::table('live_bookings')->where('id',$id)->update(['status'=>'pending_confirmation','confirmed_vendor_id'=>$v->id,'confirm_token_hash'=>hash('sha256',$token),'confirm_token_expires_at'=>now()->addMinutes(5),'updated_at'=>now()]);$url=rtrim((string)config('app.url'),'/').'/api/live-bookings/confirm/'.$token;$delivery=$b->requester_phone?\App\Services\LiveBookingWhatsAppSender::confirmation((string)$b->requester_phone,$url):['status'=>'no_phone'];if(in_array($delivery['status'],['not_configured','failed','no_phone'],true))DB::table('live_bookings')->where('id',$id)->update(['status'=>'open','confirmed_vendor_id'=>null,'confirm_token_hash'=>null,'confirm_token_expires_at'=>null,'updated_at'=>now()]);return response()->json(['status'=>true,'message'=>$delivery['status']==='sent'?'Confirmation link sent to requester. Booking remains visible until confirmed.':'Could not send confirmation link. Booking remains open for all vendors.','whatsapp_delivery'=>$delivery['status']]);},3);}
 public function requesterConfirm(string $token){$hash=hash('sha256',$token);return DB::transaction(function()use($hash){$b=DB::table('live_bookings')->where('confirm_token_hash',$hash)->lockForUpdate()->first();abort_unless($b&&$b->status==='pending_confirmation'&&$b->confirm_token_expires_at&&now()->lt($b->confirm_token_expires_at),404,'This confirmation link has expired or was already used.');$now=now();DB::table('live_bookings')->where('id',$b->id)->update(['status'=>'confirmed','confirmed_at'=>$now,'confirm_token_hash'=>null,'confirm_token_expires_at'=>null,'updated_at'=>$now]);DB::table('live_booking_interests')->where('live_booking_id',$b->id)->where('vendor_id',$b->confirmed_vendor_id)->update(['status'=>'confirmed','updated_at'=>$now]);$free=\App\Services\PartnerMarketplaceAlerts::freeCabs((int)$b->confirmed_vendor_id);$cab=collect($free)->first(fn($x)=>\App\Services\LiveBookingMatching::cab($b,$x));if($cab)DB::table('partner_market_free_cabs')->where('vehicle_id',$cab['vehicle_id'])->update(['is_free'=>false,'updated_at'=>$now]);DB::table('live_booking_vendor_cooldowns')->updateOrInsert(['vendor_id'=>$b->confirmed_vendor_id],['live_booking_id'=>$b->id,'cooldown_until'=>$now->copy()->addMinutes((int)config('live_bookings.cooldown_minutes',60)),'created_at'=>$now,'updated_at'=>$now]);return response()->view('live-booking.confirmed');},3);}
}
